// VEX U (shares V5RC rules with VEX U specific rules prioritized)
GameRuleset _getVexURuleset(String season) {
  final v5 = _getV5rcRuleset(season);
  final vexuRules = v5.rules.where((r) => r.group.toLowerCase().contains('vex u') || r.group.toLowerCase().contains('vurc')).toList();
  final otherRules = v5.rules.where((r) => !r.group.toLowerCase().contains('vex u') && !r.group.toLowerCase().contains('vurc')).toList();
  return GameRuleset(
    gameTitle: '${v5.gameTitle} (VEX U)',
    season: v5.season,
    program: 'VEX U',
    manualUrl: v5.manualUrl,
    qaUrl: 'https://events.vex.com/VEXU/${v5.season}/QA',
    rules: [...vexuRules, ...otherRules],
  );
}

// VEX AI (shares V5RC rules with VAIRC rules prioritized)
GameRuleset _getVexAiRuleset(String season) {
  final v5 = _getV5rcRuleset(season);
  final aiRules = v5.rules.where((r) => r.group.toLowerCase().contains('vairc') || r.group.toLowerCase().contains('vex ai') || r.code.contains('VAIC')).toList();
  final otherRules = v5.rules.where((r) => !r.group.toLowerCase().contains('vairc') && !r.group.toLowerCase().contains('vex ai') && !r.code.contains('VAIC')).toList();
  return GameRuleset(
    gameTitle: '${v5.gameTitle} (VEX AI)',
    season: v5.season,
    program: 'VEX AI',
    manualUrl: v5.manualUrl,
    qaUrl: 'https://events.vex.com/VAIRC/${v5.season}/QA',
    rules: [...aiRules, ...otherRules],
  );
}

GameRuleset _getV5rcRuleset(String? season) {
  switch (season) {
    case '2023-2024':
      return _v5rc20232024Ruleset;
    case '2024-2025':
      return _v5rc20242025Ruleset;
    case '2025-2026':
      return _v5rc20252026Ruleset;
    case '2026-2027':
    default:
      return _v5rc20262027Ruleset;
  }
}

GameRuleset _getViqrcRuleset(String? season) {
  switch (season) {
    case '2023-2024':
      return _viqrc20232024Ruleset;
    case '2024-2025':
      return _viqrc20242025Ruleset;
    case '2025-2026':
      return _viqrc20252026Ruleset;
    case '2026-2027':
    default:
      return _viqrc20262027Ruleset;
  }
}

/// Retrieve the active [GameRuleset] for the current tournament program and season.
GameRuleset getGameRuleset(String? program, String? season) {
  final prog = (program ?? 'V5RC').toUpperCase();
  final normalizedSeason = season ?? '2026-2027';

  if (prog.contains('IQ') || prog == 'VIQRC') {
    return _getViqrcRuleset(normalizedSeason);
  }
  if (prog.contains('U') || prog == 'VEX U' || prog == 'VURC') {
    return _getVexURuleset(normalizedSeason);
  }
  if (prog.contains('AI') || prog == 'VEX AI' || prog == 'VAIRC') {
    return _getVexAiRuleset(normalizedSeason);
  }
  return _getV5rcRuleset(normalizedSeason);
}
